  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "alerts": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "affected_customers": {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "affected_orders": {
            "items": {
              "type": "string"
