          "affected_programs": {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "affected_products": {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "business_action": {
            "type": "string"
          },
          "constrained_inventory": {
            "type": "boolean"
          },
          "exposure_kind": {
            "enum": [
              "physical_supply",
              "demand_acceleration",
              "regulatory_compliance",
              "reputational",
              "procurement_arbitrage",
              "capacity_reallocation"
            ],
            "type": "string"
          },
          "latent_edge": {
